private <T> TreeNode<T> rotateRight(TreeNode<T> node) {
    Objects.requireNonNull(node, "Node cannot be null");
    TreeNode<T> leftChild = node.left;
    Objects.requireNonNull(leftChild, "Left child cannot be null for right rotation");
    node.left = leftChild.right;
    leftChild.right = node;
    return leftChild;
}

