public class SymbolTable {
    private Map<String, Integer> typeTable;
    private int nextIndex;

    public SymbolTable() {
        typeTable = new HashMap<>();
        nextIndex = 0;
    }

    public int addType(final String value) {
        if (typeTable.containsKey(value)) {
            return typeTable.get(value);
        } else {
            typeTable.put(value, nextIndex);
            return nextIndex++;
        }
    }

    public static void main(String[] args) {
        SymbolTable symbolTable = new SymbolTable();
        System.out.println(symbolTable.addType("java/lang/String")); // Output: 0
        System.out.println(symbolTable.addType("java/util/List"));   // Output: 1
        System.out.println(symbolTable.addType("java/lang/String")); // Output: 0
    }
}

import java.lang.reflect.ParameterizedType;
import java.lang.reflect.Type;
import java.lang.reflect.TypeVariable;

public class TypeResolver {

    public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
        if (genericType instanceof ParameterizedType) {
            ParameterizedType parameterizedType = (ParameterizedType) genericType;
            Type[] actualTypeArguments = parameterizedType.getActualTypeArguments();
            TypeVariable<?>[] typeVariables = targetType.getTypeParameters();

            Class<?>[] resolvedArguments = new Class<?>[typeVariables.length];
            for (int i = 0; i < typeVariables.length; i++) {
                for (int j = 0; j < actualTypeArguments.length; j++) {
                    if (typeVariables[i].equals(actualTypeArguments[j])) {
                        if (actualTypeArguments[j] instanceof Class) {
                            resolvedArguments[i] = (Class<?>) actualTypeArguments[j];
                        } else {
                            return null; // Cannot resolve type variable further
                        }
                    }
                }
            }
            return resolvedArguments;
        }
        return null; // Not parameterized
    }

    public static void main(String[] args) {
        // Example usage
        Type genericType = new ParameterizedType() {
            @Override
            public Type[] getActualTypeArguments() {
                return new Type[]{String.class, Integer.class};
            }

            @Override
            public Type getRawType() {
                return Object.class;
            }

            @Override
            public Type getOwnerType() {
                return null;
            }
        };

        Class<?>[] resolvedArguments = resolveArguments(genericType, ExampleClass.class);
        if (resolvedArguments != null) {
            for (Class<?> type : resolvedArguments) {
                System.out.println(type.getName());
            }
        } else {
            System.out.println("Arguments could not be resolved.");
        }
    }
}

