import java.time.LocalDate;
import java.time.format.DateTimeFormatter;
import java.time.temporal.WeekFields;
import java.util.Locale;

public class TimeBucketCompressor {
    static long compressTimeBucket(long timeBucket, int dayStep) {
        DateTimeFormatter formatter = DateTimeFormatter.ofPattern("yyyyMMdd");
        LocalDate date = LocalDate.parse(String.valueOf(timeBucket), formatter);
        int dayOfMonth = date.getDayOfMonth();
        int newDayOfMonth = (dayOfMonth - 1) / dayStep * dayStep + 1;
        LocalDate newDate = date.withDayOfMonth(newDayOfMonth);
        return Long.parseLong(newDate.format(formatter));
    }

    public static void main(String[] args) {
        System.out.println(compressTimeBucket(20000105, 11)); // 20000101
        System.out.println(compressTimeBucket(20000115, 11)); // 20000112
        System.out.println(compressTimeBucket(20000123, 11)); // 20000123
    }
}

import java.nio.charset.StandardCharsets;

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    int size = 0;
    int i = index;
    final int end = index + len;
    while (i < end) {
        final char ch = str.charAt(i++);
        if (ch < 0x80) {
            size++;
        } else if (ch < 0x800) {
            size += 2;
        } else if (Character.isSurrogate(ch)) {
            final char highSurrogate = ch;
            final char lowSurrogate = str.charAt(i++);
            final int codePoint = Character.toCodePoint(highSurrogate, lowSurrogate);
            size += 4;
        } else {
            size += 3;
        }
    }
    return size;
}

