import java.util.Arrays;

public class ByteVector {
    private byte[] data;
    private int length;

    public ByteVector() {
        this.data = new byte[64];
        this.length = 0;
    }

    public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
        if (byteLength > 0) {
            ensureCapacity(length + byteLength);
            if (byteArrayValue == null) {
                Arrays.fill(data, length, length + byteLength, (byte) 0);
            } else {
                System.arraycopy(byteArrayValue, byteOffset, data, length, byteLength);
            }
            length += byteLength;
        }
        return this;
    }

    private void ensureCapacity(int capacity) {
        if (capacity > data.length) {
            int newSize = Math.max(data.length * 2, capacity);
            data = Arrays.copyOf(data, newSize);
        }
    }

    public static void main(String[] args) {
        ByteVector bv = new ByteVector();
        bv.putByteArray(new byte[]{1, 2, 3}, 0, 3);
        bv.putByteArray(null, 0, 2);
        System.out.println(Arrays.toString(bv.data));
    }
}

