import java.util.Properties;

public static String findAndSubst(String key, Properties props) {
    String value = props.getProperty(key);
    if (value == null) {
        return null;
    }
    return substVars(value, props);
}

private static String substVars(String val, Properties props) {
    StringBuilder ret = new StringBuilder();
    int prev = 0;
    int pos;
    while ((pos = val.indexOf("$", prev)) >= 0) {
        if (pos > 0 && val.charAt(pos - 1) == '\\') {
            ret.append(val.substring(prev, pos - 1)).append('$');
            prev = pos + 1;
        } else {
            int endName = val.indexOf('}', pos);
            if (endName < 0) {
                ret.append(val.substring(prev));
                prev = val.length();
                break;
            }
            String var = val.substring(pos + 2, endName);
            String replacement = System.getProperty(var, props.getProperty(var, ""));
            ret.append(val.substring(prev, pos)).append(replacement);
            prev = endName + 1;
        }
    }
    if (prev < val.length()) {
        ret.append(val.substring(prev));
    }
    return ret.toString();
}

