public class URIDecoder {
    public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
        List<PathSegmentImpl> pathSegments = new ArrayList<>();
        String path = u.getRawPath();
        if (path == null || path.isEmpty()) {
            return pathSegments;
        }

        // If the path is absolute, ignore the leading '/'
        if (path.startsWith("/")) {
            path = path.substring(1);
        }

        String[] segments = path.split("/");
        for (String segment : segments) {
            if (decode) {
                try {
                    segment = URLDecoder.decode(segment, "UTF-8");
                } catch (UnsupportedEncodingException e) {
                    // Handle the exception according to your needs
                    e.printStackTrace();
                }
            }
            pathSegments.add(new PathSegmentImpl(segment));
        }

        return pathSegments;
    }
}

class PathSegmentImpl {
    private String pathSegment;

    public PathSegmentImpl(String pathSegment) {
        this.pathSegment = pathSegment;
