import org.jbox2d.common.Vec2;
import org.jbox2d.collision.shapes.PolygonShape;
import org.javatuples.Pair;

public class BoxSplitter {
    public static Pair<Box2D, Box2D> splitAlongXAxis(Box2D box) {
        Vec2 center = box.getCenter();
        float width = box.getWidth();
        float height = box.getHeight();

        float halfWidth = width / 2.0f;

        Box2D leftBox = new Box2D(new Vec2(center.x - halfWidth / 2.0f, center.y), halfWidth, height, box.getRotation());
        Box2D rightBox = new Box2D(new Vec2(center.x + halfWidth / 2.0f, center.y), halfWidth, height, box.getRotation());

        return Pair.with(leftBox, rightBox);
    }

    public static class Box2D {
        private Vec2 center;
        private float width;
        private float height;
        private float rotation;

        public Box2D(Vec2 center, float width, float height, float rotation) {
            this.center = center;
            this.width = width;
            this.height = height;
            this.rotation = rotation;
        }

        public Vec2 getCenter() {
            return center;
        }

        public float getWidth() {
            return width;
        }

        public float getHeight() {
