public class LinkedBufferWriter {
    public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
        int totalSize = 0;
        while (node != null) {
            int size = node.limit - node.start;
            out.write(node.buffer, node.start, size);
            totalSize += size;
            node = node.next;
        }
        return totalSize;
    }
}

