import java.util.ArrayList;
import java.util.List;

class StackMapTableWriter {
    private List<String> currentFrame;
    private List<byte[]> stackMapTableEntries;

    public StackMapTableWriter() {
        this.currentFrame = new ArrayList<>();
        this.stackMapTableEntries = new ArrayList<>();
    }

    private void putAbstractTypes(final int start, final int end) {
        for (int i = start; i < end; i++) {
            String type = currentFrame.get(i);
            // Assuming type is a simple class name, convert it to JVMS verification_type_info format
            if (type.equals("int") || type.equals("float")) {
                stackMapTableEntries.add(new byte[]{0x01}); // int
            } else if (type.equals("double") || type.equals("long")) {
                stackMapTableEntries.add(new byte[]{0x03}); // double/long
            } else if (type.equals("null")) {
                stackMapTableEntries.add(new byte[]{0x05}); // null
            } else if (type.equals("uninitializedThis")) {
                stackMapTableEntries.add(new byte[]{0x06}); // uninitializedThis
            } else {
                byte[] classType = type.getBytes();
                byte[] entry = new byte[classType.length + 1];
                entry[0] = 0x07; // Object
                System.arraycopy(classType, 0, entry, 1, classType.length);
                stackMapTableEntries.add(entry);
            }
        }
    }

    public static void main(String[] args) {
        StackMapTableWriter writer = new StackMapTableWriter();
        writer.currentFrame.add("int");
        writer.currentFrame.add("java.lang.Object");
        writer.putAbstractTypes(0, writer.currentFrame.size());
    }
}

