public class CategoryTreeManager {
    private Category root;

    public CategoryTreeManager(Category root) {
        this.root = root;
    }

    protected int removeUnusedNodes() {
        return removeInactiveNodes(root);
    }

    private int removeInactiveNodes(Category node) {
        int removedCount = 0;
        List<Category> childrenToRemove = new ArrayList<>();
        for (Category child : node.getChildren()) {
            if (!child.isActive()) {
                childrenToRemove.add(child);
                removedCount++;
            } else {
                removedCount += removeInactiveNodes(child);
            }
        }
        for (Category child : childrenToRemove) {
            node.removeChild(child);
        }
        return removedCount;
    }

    public static void main(String[] args) {
        Category root = new Category(true);
        Category child1 = new Category(false);
        Category child2 = new Category(true);
        Category child3 = new Category(false);
        root.addChild(child1);
        root.addChild(child2);
        child2.addChild(child3);

        CategoryTreeManager manager = new CategoryTreeManager(root);
        System.out.println("Removed nodes count: " + manager.removeUnusedNodes());
    }
}

