import java.io.ByteArrayInputStream;
import java.io.DataInputStream;
import java.io.IOException;

final class ClassFileReader {
    private final byte[] classFileBuffer;

    public ClassFileReader(byte[] classFileBuffer) {
        this.classFileBuffer = classFileBuffer;
    }

    final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer) {
        int index = 0; // This index should be set to the start of the constant pool in classFileBuffer
        try (DataInputStream dataInputStream = new DataInputStream(new ByteArrayInputStream(classFileBuffer))) {
            // Skip magic, minor and major version
            dataInputStream.readInt();
            dataInputStream.readShort();
            dataInputStream.readShort();

            int constantPoolCount = dataInputStream.readShort();
            for (int i = 1; i < constantPoolEntryIndex; i++) {
                int tag = dataInputStream.readUnsignedByte();
                switch (tag) {
                    case 1: // CONSTANT_Utf8
                        dataInputStream.readShort(); // Skip length
                        break;
                    case 3: // CONSTANT_Integer
                    case 4: // CONSTANT_Float
                        dataInputStream.readInt();
                        break;
                    case 5: // CONSTANT_Long
                    case 6: // CONSTANT_Double
                        dataInputStream.readLong();
                        i++; // These take two entries in the constant pool
                        break;
                    case 7: // CONSTANT_Class
                    case 8: // CONSTANT_String
                    case 16: // CONSTANT_MethodHandle
                    case 18: // CONSTANT_MethodType
                    case 19: // CONSTANT_Dynamic
                    case 20: // CONSTANT_InvokeDynamic
                        dataInputStream.readShort();
                        break;
                    case 15: // CONSTANT_MethodType
                        dataInputStream.readShort();
                        break;
                    case 12: // CONSTANT_NameAndType
                        dataInputStream.readShort();
                        dataInputStream.readShort();
                        break;
                    case 17: // CONSTANT_Module
                    case 18: // CONSTANT_Package
