import java.util.Arrays;

public class ByteVector {
    private byte[] data;
    private int length;

    public ByteVector() {
        this.data = new byte[10];
        this.length = 0;
    }

    public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
        if (byteArrayValue == null) {
            ensureCapacity(byteLength);
            Arrays.fill(data, length, length + byteLength, (byte) 0);
            length += byteLength;
        } else {
            ensureCapacity(byteLength);
            System.arraycopy(byteArrayValue, byteOffset, data, length, byteLength);
            length += byteLength;
        }
        return this;
    }

    private void ensureCapacity(int additionalCapacity) {
        int newLength = length + additionalCapacity;
        if (newLength > data.length) {
            int newSize = Math.max(data.length * 2, newLength);
            data = Arrays.copyOf(data, newSize);
        }
    }

    public static void main(String[] args) {
        ByteVector bv = new ByteVector();
        bv.putByteArray(new byte[]{1, 2, 3, 4, 5}, 1, 3);
        System.out.println(Arrays.toString(bv.data)); // Output: [2, 3, 4, 0, 0, 0, 0, 0, 0, 0]
