import java.util.Stack;

private void pop(final String descriptor) {
    Stack<Object> outputFrameStack = new Stack<>();
    int currentPos = 0;
    while (currentPos < descriptor.length()) {
        char c = descriptor.charAt(currentPos++);
        switch (c) {
            case 'B':
            case 'C':
            case 'D':
            case 'F':
            case 'I':
            case 'S':
            case 'Z':
                outputFrameStack.pop();
                break;
            case 'J':
                outputFrameStack.pop();
                outputFrameStack.pop();
                break;
            case 'L':
                // Consume the class name
                while (currentPos < descriptor.length() && descriptor.charAt(currentPos) != ';') {
                    currentPos++;
                }
                outputFrameStack.pop();
                break;
            case '[':
                // Consume the rest of the array descriptor
                while (c == '[') {
                    c = descriptor.charAt(currentPos++);
                }
                if (c == 'L') {
                    // Consume the class name
                    while (currentPos < descriptor.length() && descriptor.charAt(currentPos) != ';') {
                        currentPos++;
                    }
                }
                outputFrameStack.pop();
                break;
            case '(':
                // Method descriptor, parse argument types
                while (currentPos < descriptor.length() && descriptor.charAt(currentPos) != ')') {
                    pop(descriptor.substring(currentPos, currentPos + 1));
                }
                currentPos++; // Skip the ')'
                break;
            default:
                throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
        }
    }
}

